import{_ as n,o as i,c as t,am as e}from"./chunks/framework.CiF4W93w.js";const u=JSON.parse('{"title":"Spring学习_基础内容","description":"","frontmatter":{"title":"Spring学习_基础内容","excerpt":"Spring学习_基础内容","date":"2023-11-27 17:08:54","updated":"2023-11-27 17:08:54"},"headers":[],"relativePath":"框架/框架 Spring家族/框架 Spring/Spring学习_基础内容.md","filePath":"框架/框架 Spring家族/框架 Spring/Spring学习_基础内容.md","lastUpdated":null}'),p={name:"框架/框架 Spring家族/框架 Spring/Spring学习_基础内容.md"};function s(a,r,o,g,l,c){return i(),t("div",null,[...r[0]||(r[0]=[e('<blockquote><p>大纲</p></blockquote><ul><li>Spring 概念</li><li>常用模块</li><li>IOC</li><li>AOP</li><li>Spring 事务</li><li>Spring MVC</li></ul><h3 id="spring-介绍" tabindex="-1">Spring 介绍 <a class="header-anchor" href="#spring-介绍" aria-label="Permalink to &quot;Spring 介绍&quot;">​</a></h3><blockquote><p>什么是Spring</p></blockquote><p>Spring 是一个轻量级的开源Java开发框架，旨在提高开发人员的开发效率以及系统的可维护性。</p><p>一般来说，我们常说的 Spring 框架指的是 Spring Framework, 他是多模块的一个集合，这些模块能够比较方便的帮助我们来进行开发。</p><p>Spring 有很多特性，也支持很多功能，了解Spring 框架，我们一般会从它支持的 IOC 和 AOP 这两个核心功能来最开始认识它。</p><p><strong>目前Spring 最大的一个优势是它构建了一个非常不错的Java生态，你能够在这里面找到不同需求需要的处理方案。</strong></p><p>Spring 的官网： <a href="https://spring.io/" target="_blank" rel="noreferrer">https://spring.io/</a></p><p>Github地址： <a href="https://github.com/spring-projects/spring-framework" target="_blank" rel="noreferrer">https://github.com/spring-projects/spring-framework</a></p><p>Spring 的具体模块可以放后面了解，主要模块了解下。</p><p>Spring 5.x 主要模块</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231201212051.png" alt="image.png"> 各个模块的依赖关系</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231201212107.png" alt="image.png"></p><blockquote><p>Core Container</p></blockquote><p>其中主要模块中，Core Container 是 Spring 框架的核心模块，也是基础模块，它提供了 IOC 的依赖注入功能，Spring 的<strong>其他模块实现的功能也是在依赖该模块的基础上进行实现的</strong>。</p><p>Core Container 的子模块：</p><ul><li><strong>spring-core</strong>：Spring 框架基本的核心工具类。</li><li><strong>spring-beans</strong>：提供对 bean 的创建、配置和管理等功能的支持。</li><li><strong>spring-context</strong>：提供对国际化、事件传播、资源加载等功能的支持。</li><li><strong>spring-expression</strong>：提供对表达式语言（Spring Expression Language） SpEL 的支持，只依赖于 core 模块，不依赖于其他模块，可以单独使用</li></ul><blockquote><p>AOP</p></blockquote><ul><li><strong>spring-aspects</strong>：该模块为与 AspectJ 的集成提供支持。</li><li><strong>spring-aop</strong>：提供了面向切面的编程实现。</li><li><strong>spring-instrument</strong>：提供了为 JVM 添加代理（agent）的功能。 具体来讲，它为 Tomcat 提供了一个织入代理，能够为 Tomcat 传递类文 件，就像这些文件是被类加载器加载的一样。(这个模块的使用场景非常有限)</li></ul><h3 id="spring-循环依赖-🚩" tabindex="-1">Spring 循环依赖 🚩 <a class="header-anchor" href="#spring-循环依赖-🚩" aria-label="Permalink to &quot;Spring 循环依赖  🚩&quot;">​</a></h3><p>参考： <a href="https://wx.zsxq.com/dweb2/index/columns/48418884588288" target="_blank" rel="noreferrer">https://wx.zsxq.com/dweb2/index/columns/48418884588288</a></p><hr><p>参考</p><ul><li><a href="https://javaguide.cn/system-design/framework/spring/spring-knowledge-and-questions-summary.html" target="_blank" rel="noreferrer">https://javaguide.cn/system-design/framework/spring/spring-knowledge-and-questions-summary.html</a></li><li><a href="https://www.pdai.tech/md/spring/spring.html" target="_blank" rel="noreferrer">https://www.pdai.tech/md/spring/spring.html</a></li><li><a href="https://blog.csdn.net/Mixzi/article/details/123980213" target="_blank" rel="noreferrer">https://blog.csdn.net/Mixzi/article/details/123980213</a></li><li><a href="https://www.moguit.cn/info/794" target="_blank" rel="noreferrer">https://www.moguit.cn/info/794</a></li></ul>',25)])])}const m=n(p,[["render",s]]);export{u as __pageData,m as default};
